findings.codeql_raw_query:
/**
 * @name Unsafe dynamic import
 * @description Dynamic imports with user-controlled module names can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-dynamic-import
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UnsafeDynamicImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("importlib").getMember("import_module").getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeDynamicImportFlow = TaintTracking::Global<UnsafeDynamicImportConfig>;
import UnsafeDynamicImportFlow::PathGraph

from UnsafeDynamicImportFlow::PathNode source, UnsafeDynamicImportFlow::PathNode sink
where UnsafeDynamicImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic import with untrusted module name from $@.", source.getNode(), "user input"
